def is_subsequence(s, sub):
    it = iter(s)
    return all(c in it for c in sub)

def running_max(nums):
    result = []
    current = None
    for n in nums:
        if current is None or n > current:
            current = n
        result.append(current)
    return result

def rotate_right(lst):
    if not lst:
        return []
    return [lst[-1]] + lst[:-1]
